=== plugin-api (the whole contract) ===
import { Type, type Static } from "@sinclair/typebox";
import { Value } from "@sinclair/typebox/value";

export const LOBU_PLUGIN_API_VERSION = 1 as const;

export const PluginManifestSchema = Type.Object(
  {
    name: Type.String({ pattern: "^[a-z][a-z0-9-]*$" }),
    version: Type.String({ minLength: 1 }),
    apiVersion: Type.Literal(LOBU_PLUGIN_API_VERSION),
    description: Type.String({ minLength: 1 }),
  },
  { additionalProperties: false }
);

export type PluginManifest = Static<typeof PluginManifestSchema>;

export interface PluginLogger {
  debug(message: string, data?: Record<string, unknown>): void;
  info(message: string, data?: Record<string, unknown>): void;
  warn(message: string, data?: Record<string, unknown>): void;
  error(message: string, data?: Record<string, unknown>): void;
}

export interface PluginRuntimeContext {
  logger: PluginLogger;
  organizationId: string;
  actorId: string;
  credentialSubject: string;
  destination: string;
  agentId: string;
  conversationId: string;
  runId: number;
  messageId: string;
  connectionId?: string;
  workspaceDir: string;
  platform: string;
}

export interface BeforeAgentStartEvent {
  prompt: string;
  messages: readonly unknown[];
}

export interface BeforeAgentStartResult {
  prependContext?: string;
}

export interface AgentEndEvent {
  messages: readonly unknown[];
  error?: string;
}

export interface PluginHooks {
  beforeAgentStart?(
    event: BeforeAgentStartEvent,
    context: PluginRuntimeContext
  ):
    | BeforeAgentStartResult
    | undefined
    | Promise<BeforeAgentStartResult | undefined>;
  agentEnd?(
    event: AgentEndEvent,
    context: PluginRuntimeContext
  ): void | Promise<void>;
}

export interface LobuPlugin<TTool = never> {
  manifest: PluginManifest;
  hooks?: PluginHooks;
  tools?(
    context: PluginRuntimeContext
  ): readonly TTool[] | Promise<readonly TTool[]>;
}

export function defineLobuPlugin<TTool = never>(
  plugin: LobuPlugin<TTool>
): LobuPlugin<TTool> {
  assertPluginManifest(plugin.manifest);
  return plugin;
}

export function assertPluginManifest(
  manifest: unknown
): asserts manifest is PluginManifest {
  if (Value.Check(PluginManifestSchema, manifest)) {
    return;
  }
  const errors = [...Value.Errors(PluginManifestSchema, manifest)]
    .map((error) => `${error.path || "/"}: ${error.message}`)
    .join("; ");
  throw new Error(`Invalid Lobu plugin manifest: ${errors}`);
}

=== plugin-host (the whole host) ===
import {
  type AgentEndEvent,
  assertPluginManifest,
  type BeforeAgentStartEvent,
  type LobuPlugin,
  type PluginRuntimeContext,
} from "@lobu/plugin-api";

export class PluginHost<TTool = never> {
  readonly plugins: readonly LobuPlugin<TTool>[];

  constructor(plugins: readonly LobuPlugin<TTool>[]) {
    const names = new Set<string>();
    for (const plugin of plugins) {
      assertPluginManifest(plugin.manifest);
      if (names.has(plugin.manifest.name)) {
        throw new Error(`Duplicate Lobu plugin: ${plugin.manifest.name}`);
      }
      names.add(plugin.manifest.name);
    }
    this.plugins = [...plugins];
  }

  async tools(context: PluginRuntimeContext): Promise<TTool[]> {
    const tools: TTool[] = [];
    const names = new Set<string>();
    for (const plugin of this.plugins) {
      if (!plugin.tools) continue;
      for (const tool of await plugin.tools(context)) {
        const name = contributionName(tool);
        if (name && names.has(name)) {
          throw new Error(`Duplicate Lobu plugin tool: ${name}`);
        }
        if (name) names.add(name);
        tools.push(tool);
      }
    }
    return tools;
  }

  async beforeAgentStart(
    event: BeforeAgentStartEvent,
    context: PluginRuntimeContext
  ): Promise<string[]> {
    const prependContext: string[] = [];
    for (const plugin of this.plugins) {
      const result = await plugin.hooks?.beforeAgentStart?.(event, context);
      const value = result?.prependContext?.trim();
      if (value) prependContext.push(value);
    }
    return prependContext;
  }

  async agentEnd(
    event: AgentEndEvent,
    context: PluginRuntimeContext
  ): Promise<void> {
    for (const plugin of this.plugins) {
      try {
        await plugin.hooks?.agentEnd?.(event, context);
      } catch (error) {
        context.logger.error("Plugin agentEnd hook failed", {
          plugin: plugin.manifest.name,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }
  }
}

function contributionName(value: unknown): string | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const contribution = value as { id?: unknown; name?: unknown };
  if (typeof contribution.name === "string" && contribution.name) {
    return contribution.name;
  }
  return typeof contribution.id === "string" && contribution.id
    ? contribution.id
    : undefined;
}

