11	import { __testing, rewriteWorkspaceRefs } from "../publish-packages.mjs";
12	
13	function workerManifest() {
14	  return {
15	    name: "@lobu/worker",
16	    version: "14.3.0",
17	    dependencies: {
18	      "@lobu/core": "workspace:*",
19	      "@lobu/plugin-api": "workspace:*",
20	      "@lobu/plugin-host": "workspace:*",
21	      "@lobu/plugin-mcp": "workspace:*",
22	      "@lobu/plugin-memory": "workspace:*",
23	    },
24	  };
25	}
26	
27	describe("rewriteWorkspaceRefs publishability guard", () => {
28	  it("refuses a runtime dependency on a package the script does not publish", () => {
29	    expect(() => rewriteWorkspaceRefs(workerManifest())).toThrow(
30	      /@lobu\/plugin-mcp/
31	    );
32	  });
33	
34	  it("names the offending package and both remedies, not just 'failed'", () => {
35	    let message = "";
36	    try {
37	      rewriteWorkspaceRefs(workerManifest());
38	    } catch (error) {
39	      message = error instanceof Error ? error.message : String(error);
40	    }
41	    expect(message).toContain("@lobu/worker");
42	    expect(message).toContain("@lobu/plugin-mcp");
43	    expect(message).toContain("bundling");
44	    expect(message).toContain("PACKAGES");
45	  });
46	
47	  it("guards every runtime dependency section, including explicit versions", () => {
48	    for (const section of [
49	      "dependencies",
50	      "optionalDependencies",
51	      "peerDependencies",
52	    ]) {
53	      expect(() =>
54	        rewriteWorkspaceRefs({
55	          name: "@lobu/worker",
56	          version: "14.3.0",
57	          [section]: { "@lobu/plugin-mcp": "1.2.3" },
58	        })
59	      ).toThrow(/@lobu\/plugin-mcp/);
60	    }
61	  });
62	
63	  it("still rewrites refs when every runtime dependency is published", () => {
64	    const pkg = rewriteWorkspaceRefs({
