76	    // tool is legitimate and must not trip the guard.
77	    const pkg = rewriteWorkspaceRefs({
78	      name: "@lobu/cli",
79	      version: "14.3.0",
80	      dependencies: {},
81	      devDependencies: { "@lobu/plugin-mcp": "workspace:*" },
82	    }) as { devDependencies: Record<string, string> };
83	    expect(pkg.devDependencies["@lobu/plugin-mcp"]).not.toContain("workspace:");
84	  });
