        `const log = ${JSON.stringify(logFile)};`,
        // `npm view <pkg>@<ver> version` → nothing is published yet.
        "if (args[0] === 'view') { process.exit(1); }",
        "if (args[0] === 'publish') {",
        "  const pkg = JSON.parse(fs.readFileSync('package.json','utf8'));",
        "  fs.appendFileSync(log, pkg.name + '\\n');",
