#!/bin/bash
# The real release rehearsal: apply the publish transforms to EVERY package the
# script publishes, pack them all, then install @lobu/cli from those tarballs in
# an empty directory. This is what `npx @lobu/cli@latest` resolves, and it is
# the check that would have caught #2186 before it shipped.
set -uo pipefail
export PATH="/opt/homebrew/bin:$PATH"
WT=/Users/burakemre/Code/lobu/.claude/worktrees/publish-guard-deadcode
SP=/private/tmp/claude-501/-Users-burakemre-Code-lobu/957f3182-b92b-4e7f-9988-fa5fcd2420b5/scratchpad
OUT="$SP/fleet"; CONSUMER="$SP/fleet-consumer"
PKGMGR=$(command -v npm)

rm -rf "$OUT" "$CONSUMER"; mkdir -p "$OUT" "$CONSUMER"
cd "$WT"

# Snapshot every manifest, apply the real transform, pack, then restore.
node -e "
import('./scripts/publish-packages.mjs').then(async m => {
  const fs = await import('node:fs');
  const out = [];
  for (const p of m.__testing.PACKAGES) {
    const file = p.dir + '/package.json';
    const orig = fs.readFileSync(file, 'utf8');
    fs.writeFileSync('$OUT/' + p.dir.replace(/\//g,'_') + '.orig', orig);
    const t = p.transform ? p.transform(JSON.parse(orig)) : JSON.parse(orig);
    fs.writeFileSync(file, JSON.stringify(t, null, 2) + '\n');
    out.push(p.dir);
  }
  fs.writeFileSync('$OUT/dirs.txt', out.join('\n'));
});
"

while read -r dir; do
  (cd "$dir" && "$PKGMGR" pack --pack-destination "$OUT" >/dev/null 2>&1) \
    || echo "  pack FAILED: $dir"
done < "$OUT/dirs.txt"

# Restore every manifest immediately.
while read -r dir; do
  cp "$OUT/$(echo "$dir" | tr '/' '_').orig" "$dir/package.json"
done < "$OUT/dirs.txt"

echo "packed $(ls "$OUT"/*.tgz 2>/dev/null | wc -l | tr -d ' ') tarballs"
echo

cd "$CONSUMER"
cat > package.json <<'JSON'
{ "name": "fleet-consumer", "version": "1.0.0", "private": true }
JSON

CLI=$(ls "$OUT"/lobu-cli-*.tgz 2>/dev/null)
[ -z "$CLI" ] && { echo "no cli tarball"; exit 1; }

# Force every @lobu dep to resolve from the packed tarballs, standing in for
# "this release is on the registry". Anything NOT overridden must already exist
# publicly — if the install still 404s on an @lobu name, that name is missing.
node -e "
const fs=require('fs');
const ov={};
for (const f of fs.readdirSync('$OUT').filter(f=>f.endsWith('.tgz'))) {
  const name='@lobu/'+f.replace(/^lobu-/,'').replace(/-\d+\.\d+\.\d+.*\.tgz$/,'');
  ov[name]='file:$OUT/'+f;
}
const p=JSON.parse(fs.readFileSync('package.json','utf8'));
p.overrides=ov; fs.writeFileSync('package.json',JSON.stringify(p,null,2));
console.log('overrides:', Object.keys(ov).join(' '));
"
echo
echo "=== installing @lobu/cli from the packed fleet ==="
"$PKGMGR" install --omit=dev --no-audit --no-fund "$CLI" 2>&1 | tail -8
echo
echo "=== exit: ${PIPESTATUS[0]} ==="
echo "=== installed @lobu packages ==="
ls node_modules/@lobu 2>/dev/null || echo "(none)"

